            .field("calls", &self.calls)
            .field("path", &self.path)
            .field(
                "history_lens",
                &self.histories.iter().map(Vec::len).collect::<Vec<_>>(),
            )
            .field("transfers", &self.transfers)
            .field("level", &self.level)
            .finish()
    }
}

