#[tokio::test]
async fn allow_path_invokes_and_redacts_extra_secret() {
    let ctx = noop_run_context::<()>().with_extra_secrets(vec!["supersecretvalue".into()]);
    let tool_ctx = ctx.to_tool_context();
    let tool = MockTool::new(
        "secret",
